<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue'
import {useRouter} from 'vue-router'
import type {QForm} from 'quasar'
import {matArrowBack,matFactCheck,matArrowForward} from '@quasar/extras/material-icons'
import {request} from '../lib/api'
import ConfigFields from '../components/ConfigFields.vue'
import type {Bootstrap,ScanConfig,Proxy,CredentialSet,Profile,Page,Preview,Job} from '../types'
const router=useRouter(),form=ref<QForm|null>(null),boot=ref<Bootstrap|null>(null),config=ref<ScanConfig|null>(null)
const proxies=ref<Proxy[]>([]),credentials=ref<CredentialSet[]>([]),profiles=ref<Profile[]>([]),profileID=ref('')
const name=ref(''),priority=ref(3),delayed=ref(false),scheduled=ref(''),preview=ref<Preview|null>(null),authorized=ref(false),loading=ref(true),pending=ref(false),error=ref('')
const controller=new AbortController();let validatedAgainst='',intent={digest:'',key:''}
const templateID=ref('manual')
const templates=[{label:'Manual / current settings',value:'manual'},{label:'HTTP/HTTPS via proxy',value:'http-proxy'},{label:'HTTP/HTTPS direct',value:'http-direct'},{label:'Camera discovery · TCP connect',value:'camera-connect'}]
function applyTemplate(id:string){
 templateID.value=id;error.value='';preview.value=null;authorized.value=false
 if(!config.value||id==='manual')return
 profileID.value=''
 const web=id==='http-proxy'||id==='http-direct'
 const credentialID=config.value.credential_set_id||credentials.value.find(s=>s.name.startsWith('CCTVScan defaults'))?.id||''
 config.value={...config.value,port_mode:web?'custom':'camera',ports:web?'80,443':'',scan_mode:'connect',onvif:false,capture:false,check_credentials:web&&boot.value?.policy.allow_credentials===true&&!!credentialID,credential_set_id:credentialID,proxy_version_id:id==='http-direct'?'':config.value.proxy_version_id}
}
function copy<T>(value:T):T{return JSON.parse(JSON.stringify(value))}
async function load(){loading.value=true;error.value='';try{const [b,p,c,s]=await Promise.all([request<Bootstrap>('/bootstrap',{signal:controller.signal}),request<Page<Proxy>>('/proxies',{signal:controller.signal}),request<Page<CredentialSet>>('/credential-sets',{signal:controller.signal}),request<Page<Profile>>('/profiles',{signal:controller.signal})]);if(controller.signal.aborted)return;boot.value=b;config.value=copy(b.defaults);const defaults=c.items.find(s=>s.name.startsWith('CCTVScan defaults'));if(defaults&&b.policy.allow_credentials===true){config.value.credential_set_id=defaults.id;config.value.check_credentials=true}proxies.value=p.items;credentials.value=c.items;profiles.value=s.items}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'Could not load scan settings.'}finally{if(!controller.signal.aborted)loading.value=false}}
function useProfile(id:string){profileID.value=id;const p=profiles.value.find(v=>v.id===id);if(!p)return;templateID.value='manual';error.value='';config.value={...copy(p.config),check_credentials:false,capture:false,onvif:false};if(!name.value)name.value=`${p.name} run`}
watch(config,()=>{preview.value=null;authorized.value=false},{deep:true})
async function inspect(){if(templateID.value==='http-proxy'&&!config.value?.proxy_version_id){error.value='Select a proxy profile for this template.';return}if(!config.value||!await form.value?.validate())return;pending.value=true;error.value='';const source=JSON.stringify(config.value);try{const p=await request<Preview>('/jobs/preview',{method:'POST',body:{config:copy(config.value)},signal:controller.signal});if(source!==JSON.stringify(config.value)){error.value='The configuration changed. Preview it again before queueing.';return}validatedAgainst=source;preview.value=p;authorized.value=false}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'The plan could not be validated.'}finally{pending.value=false}}
async function queue(){if(!preview.value||!config.value||validatedAgainst!==JSON.stringify(config.value)){error.value='Preview the current configuration before queueing.';return}if(!authorized.value){error.value='Confirm authorization for this scope and the enabled actions.';return}if(!await form.value?.validate())return;pending.value=true;error.value='';try{const payload={name:name.value.trim(),config:copy(preview.value.config),priority:priority.value,...(delayed.value?{scheduled_at:new Date(scheduled.value).toISOString()}:{})};const digest=JSON.stringify(payload);if(intent.digest!==digest)intent={digest,key:crypto.randomUUID()};const job=await request<Job>('/jobs',{method:'POST',body:{...payload,idempotency_key:intent.key},signal:controller.signal});await router.push(`/jobs/${encodeURIComponent(job.id)}`)}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'The job could not be queued. Refresh the queue before trying again.'}finally{pending.value=false}}
onMounted(load);onBeforeUnmount(()=>controller.abort())
</script>
<template>
 <q-page class="workspace composer-workspace"><header class="page-header"><div><q-btn class="back-link" flat dense :icon="matArrowBack" label="Job dispatch" @click="router.push('/jobs')"/><h1>Define the work.</h1><p class="page-description">Set an exact scope. Inspect the plan. Then put the runner to work.</p></div></header>
  <div v-if="error" role="alert" class="error-banner"><span>{{error}}</span><q-btn v-if="!boot" flat label="Try again" @click="load"/></div>
  <div v-if="loading" class="loading-label" role="status">Loading server policy and saved configuration…</div>
  <q-form v-else-if="boot&&config" ref="form" @submit="queue" class="composer-layout">
   <div class="surface composer-form"><section class="form-section"><q-select data-testid="scan-template" :model-value="templateID" @update:model-value="applyTemplate" outlined emit-value map-options label="Scan template" :options="templates" hint="Choose a starting point, then adjust any setting."/></section><section class="form-section"><h2>Job identity</h2><div class="config-grid"><q-input v-model="name" outlined label="Job name" aria-label="Job name" maxlength="200" :rules="[v=>!!String(v).trim()||'Name this job.']" placeholder="Authorized perimeter assessment"/><q-select v-model="priority" outlined emit-value map-options label="Queue priority" :options="[{label:'Normal',value:3},{label:'Low',value:4},{label:'High',value:2},{label:'Urgent',value:1}]"/><q-select v-if="profiles.length" :model-value="profileID" @update:model-value="useProfile" outlined emit-value map-options label="Start from a saved profile" :options="profiles.map(p=>({label:p.name,value:p.id}))" class="span-full" hint="Sensitive opt-ins must be re-enabled for each manually created job."/></div></section>
    <ConfigFields v-model="config" :policy="boot.policy" :proxies="proxies" :credential-sets="credentials"/>
    <section class="form-section"><h2>Dispatch time</h2><q-checkbox v-model="delayed" label="Delay this one job" color="dark"/><q-input v-if="delayed" v-model="scheduled" outlined type="datetime-local" label="Not before (your local time)" class="q-mt-md" :rules="[v=>!!v&&Number.isFinite(new Date(v).getTime())&&new Date(v).getTime()>Date.now()||'Choose a valid future time.']" hint="This is a one-off delay. Runner availability still determines the actual start."/><p class="helper q-mt-md">For recurring work, create a schedule on the Schedules page instead.</p></section>
    <div class="form-actions"><q-btn flat label="Discard draft" @click="router.push('/jobs')"/><q-btn data-testid="preview-job" unelevated color="dark" :icon="matFactCheck" label="Preview execution" :loading="pending" @click="inspect"/></div>
   </div>
   <aside class="surface execution-preview" aria-label="Execution review"><span class="section-label">Before dispatch</span><template v-if="preview"><h2>Review execution</h2><dl class="detail-list"><div><dt>Requested address upper bound</dt><dd>{{preview.requested_address_upper_bound.toLocaleString()}}</dd></div><div><dt>Unique ports</dt><dd>{{preview.unique_ports.toLocaleString()}}</dd></div><div><dt>Discovery</dt><dd>{{preview.config.scan_mode==='connect'?'TCP connect':preview.config.scan_mode==='syn'?'Raw SYN':'Raw + connect'}}</dd></div><div><dt>HTTP routing</dt><dd>{{preview.config.proxy_version_id?'Pinned proxy version':'Direct HTTP requests'}}</dd></div><div><dt>Whole-job deadline</dt><dd>{{preview.config.timeout_seconds}} seconds</dd></div></dl><h3>Complete scope</h3><div class="review-scope mono">{{preview.normalized_targets.join('\n')}}</div><p class="helper q-mt-sm">The address count is an upper bound; overlapping entries are not subtracted. The runner must not silently sample the scope.</p><q-expansion-item dense label="Inspect the effective port set" class="q-mb-lg"><pre class="port-set">{{preview.effective_ports}}</pre></q-expansion-item><div class="token-list q-mb-lg"><span v-if="preview.config.check_credentials" class="token">Credential checks enabled</span><span v-if="preview.config.capture" class="token">HTTP still images enabled</span><span v-if="preview.config.onvif" class="token">ONVIF UDP enabled</span><span v-if="!preview.config.check_credentials&&!preview.config.capture&&!preview.config.onvif" class="token">Sensitive actions off</span></div><q-checkbox data-testid="authorize-scope" v-model="authorized" color="dark" label="I am authorized for this complete scope and all enabled actions."/><q-btn data-testid="queue-job" class="full-width q-mt-lg" unelevated color="primary" text-color="dark" :icon-right="matArrowForward" type="submit" label="Send to queue" :disable="!authorized||pending" :loading="pending"/></template><template v-else><h2>Know what<br>you are starting.</h2><p class="helper">The server validates scope, ports, budgets and references before a job enters the queue.</p><div class="inspector-rule"/><p class="helper">Preview makes no scan requests. Editing the configuration invalidates the previous preview.</p></template><p class="inspector-footnote">Jobs and settings are stored in PostgreSQL. Closing this page does not cancel queued or running work. No continuous video playback is implied.</p></aside>
  </q-form>
 </q-page>
</template>
<style scoped>
.composer-workspace{max-width:1540px}.back-link{margin-left:-9px;margin-bottom:22px;color:var(--muted);font-size:12px}.composer-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:23px;align-items:start}.composer-form{padding:28px}.execution-preview{position:sticky;top:26px;padding:24px}.execution-preview h2{margin-top:25px;margin-bottom:18px;font-size:27px}.execution-preview h3{font-size:13px;margin-bottom:11px}.review-scope{white-space:pre-wrap;max-height:170px;overflow:auto;padding:12px;background:#edf2f4;border-radius:6px;overflow-wrap:anywhere}.port-set{white-space:pre-wrap;overflow-wrap:anywhere;max-height:180px;overflow:auto;font-size:11px}.execution-preview .q-checkbox{font-size:12px;line-height:1.6}.execution-preview .q-checkbox:deep(.q-checkbox__label){padding-left:4px}@media(max-width:1150px){.composer-layout{grid-template-columns:minmax(0,1fr) 265px;gap:18px}.composer-form{padding:23px}.execution-preview{padding:20px}}@media(max-width:800px){.composer-layout{grid-template-columns:1fr}.execution-preview{position:static}.composer-form{padding:22px 18px}}
</style>
